8	 *     http://www.apache.org/licenses/LICENSE-2.0
9	 *
10	 * Unless required by applicable law or agreed to in writing, software
11	 * distributed under the License is distributed on an "AS IS" BASIS,
12	 * WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.
13	 * See the License for the specific language governing permissions and
14	 * limitations under the License.
15	 */
16	package org.traccar.protocol;
17	
18	import io.netty.channel.Channel;
19	import org.traccar.AbstractWireDecoder;
20	import org.traccar.model.CellTower;
21	import org.traccar.session.UnitSession;
22	import org.traccar.Protocol;
23	import org.traccar.helper.DateBuilder;
24	import org.traccar.helper.FieldCursor;
25	import org.traccar.helper.GrammarComposer;
26	import org.traccar.model.Network;
27	import org.traccar.model.Position;
28	import org.traccar.model.WifiAccessPoint;
29	
30	import java.net.SocketAddress;
31	import java.util.LinkedList;
32	import java.util.List;
33	import java.util.regex.Pattern;
34	
35	public class Tlt2hProtocolDecoder extends AbstractWireDecoder {
36	
37	    public Tlt2hProtocolDecoder(Protocol protocol) {
38	        super(protocol);
39	    }
40	
41	    private static final Pattern PATTERN_HEADER = new GrammarComposer()
42	            .number("#(d+)")                     // imei
43	            .expression("#[^#]*")                // user
44	            .number("#d*")                       // password
45	            .groupBegin()
46	            .number("#([01])")                   // door
47	            .number("#(d+)")                     // fuel voltage
48	            .number("#(d+)")                     // power
49	            .number("#(d+)")                     // battery
50	            .number("#(d+)")                     // temperature
51	            .groupEnd("?")
52	            .expression("#([^#]+)")              // status
53	            .number("#d+")                       // number of records
54	            .compile();
55	
56	    private static final Pattern PATTERN_POSITION = new GrammarComposer()
57	            .text("#")
58	            .number("(?:(dd|dddd)|x*)")          // cell or voltage
59	            .groupBegin()
60	            .text("#")
61	            .groupBegin()
62	            .number("(d+),")                     // mcc
63	            .number("(d+),")                     // mnc
64	            .number("(x+),")                     // lac
65	            .number("(x+)")                      // cell id
66	            .groupEnd("?")
67	            .groupEnd("?")
68	            .text("$GPRMC,")
69	            .number("(?:(dd)(dd)(dd).d+)?,")     // time (hhmmss.sss)
70	            .expression("([AVL]),")              // validity
71	            .groupBegin()
72	            .number("(d+)(dd.d+),")              // latitude
73	            .expression("([NS]),")
74	            .number("(d+)(dd.d+),")              // longitude
75	            .number("([EW]),")
76	            .number("(d+.?d*)?,")                // speed
77	            .number("(d+.?d*)?,")                // course
78	            .number("(dd)(dd)(dd)")              // date (ddmmyy)
79	            .groupEnd("?")
80	            .any()
81	            .compile();
82	
83	    private static final Pattern PATTERN_WIFI = new GrammarComposer()
84	            .text("#")
85	            .number("(?:(dd|dddd)|x+)")          // cell or voltage
86	            .expression("#?")
87	            .groupBegin()
88	            .number("(d+),")                     // mcc
89	            .number("(d+),")                     // mnc
90	            .number("(x+),")                     // lac
91	            .number("(x+)")                      // cell id
92	            .groupEnd("?")
93	            .text("$WIFI,")
94	            .number("(dd)(dd)(dd).d+,")          // time (hhmmss.sss)
95	            .expression("[AVL],")                // validity
96	            .expression("(.*)")                  // access points
97	            .number("(dd)(dd)(dd)")              // date (ddmmyy)
98	            .text("*")
99	            .number("xx")                        // checksum
100	            .compile();
101	
102	    private void decodeStatus(Position position, String status) {
103	        switch (status) {
104	            case "AUTOSTART", "AUTO" -> position.set(Position.KEY_IGNITION, true);
105	            case "AUTOSTOP", "AUTOLOW" -> position.set(Position.KEY_IGNITION, false);
106	            case "TOWED" -> position.addAlarm(Position.ALARM_TOW);
107	            case "SHAKE" -> position.addAlarm(Position.ALARM_VIBRATION);
108	            case "SOS" -> position.addAlarm(Position.ALARM_SOS);
109	            case "DEF" -> position.addAlarm(Position.ALARM_POWER_CUT);
110	            case "BLP" -> position.addAlarm(Position.ALARM_LOW_BATTERY);
111	            case "CLP" -> position.addAlarm(Position.ALARM_LOW_POWER);
112	            case "OS" -> position.addAlarm(Position.ALARM_GEOFENCE_EXIT);
113	            case "RS" -> position.addAlarm(Position.ALARM_GEOFENCE_ENTER);
114	            case "OVERSPEED" -> position.addAlarm(Position.ALARM_OVERSPEED);
115	        }
116	    }
117	
118	    @Override
119	    protected Object decode(
120	            Channel channel, SocketAddress remoteAddress, Object msg) throws Exception {
121	
122	        String sentence = (String) msg;
123	        sentence = sentence.trim();
124	
125	        String header = sentence.substring(0, sentence.indexOf('\r'));
126	        FieldCursor parser = new FieldCursor(PATTERN_HEADER, header);
127	        if (!parser.matches()) {
128	            return null;
129	        }
130	
131	        UnitSession deviceSession = resolveUnitSession(channel, remoteAddress, parser.next());
132	        if (deviceSession == null) {
133	            return null;
134	        }
135	
136	        Boolean door = null;
137	        Double adc = null;
138	        Double power = null;
139	        Double battery = null;
140	        Double temperature = null;
141	        if (parser.hasNext(5)) {
142	            door = parser.nextInt() == 1;
143	            adc = parser.nextInt() / 10.0;
144	            power = parser.nextInt() / 10.0;
145	            battery = parser.nextInt() / 10.0;
146	            temperature = parser.nextInt() / 10.0;
147	        }
148	
149	        String status = parser.next();
150	
151	        String[] messages = sentence.substring(
152	                sentence.indexOf('\n') + 1,
153	                sentence.endsWith("##") ? sentence.length() - 4 : sentence.length())
154	                .split("\r\n");
155	        List<Position> positions = new LinkedList<>();
156	
157	        for (String message : messages) {
158	            Position position = new Position(wireName());
159	            position.setDeviceId(deviceSession.getDeviceId());
160	
161	            if (message.contains("$GPRMC")) {
162	
163	                parser = new FieldCursor(PATTERN_POSITION, message);
164	                if (parser.matches()) {
165	
166	                    if (parser.hasNext()) {
167	                        int voltage = parser.nextInt();
168	                        position.set(Position.KEY_BATTERY, voltage > 100 ? voltage / 1000.0 : voltage / 10.0);
169	                    }
170	
171	                    if (parser.hasNext(4)) {
172	                        Network network = new Network();
173	                        network.addCellTower(CellTower.from(
174	                                parser.nextInt(), parser.nextInt(), parser.nextHexInt(), parser.nextHexInt()));
175	                        position.setNetwork(network);
176	                    }
177	
178	                    DateBuilder dateBuilder = new DateBuilder();
179	                    if (parser.hasNext(3)) {
180	                        dateBuilder.setTime(parser.nextInt(), parser.nextInt(), parser.nextInt());
181	                    }
182	
183	                    position.setValid(parser.next().equals("A"));
184	
185	                    if (parser.hasNext()) {
186	
187	                        position.setLatitude(parser.nextCoordinate());
188	                        position.setLongitude(parser.nextCoordinate());
189	                        position.setSpeed(parser.nextDouble(0));
190	                        position.setCourse(parser.nextDouble(0));
191	
192	                        dateBuilder.setDateReverse(parser.nextInt(), parser.nextInt(), parser.nextInt());
193	                        position.setTime(dateBuilder.getDate());
194	
195	                    } else {
196	                        getLastLocation(position, null);
197	                    }
198	
199	                } else {
200	                    continue;
201	                }
202	
203	            } else if (message.contains("$WIFI")) {
204	
205	                parser = new FieldCursor(PATTERN_WIFI, message);
206	                if (parser.matches()) {
207	
208	                    if (parser.hasNext()) {
209	                        int voltage = parser.nextInt();
210	                        position.set(Position.KEY_BATTERY, voltage > 100 ? voltage / 1000.0 : voltage / 10.0);
211	                    }
212	
213	                    Network network = new Network();
214	                    if (parser.hasNext(4)) {
215	                        network.addCellTower(CellTower.from(
216	                                parser.nextInt(), parser.nextInt(), parser.nextHexInt(), parser.nextHexInt()));
217	                    }
218	
219	                    DateBuilder dateBuilder = new DateBuilder()
220	                            .setTime(parser.nextInt(), parser.nextInt(), parser.nextInt());
221	
222	                    String[] values = parser.next().split(",");
223	                    for (int i = 0; i < values.length / 2; i++) {
224	                        String mac = values[i * 2 + 1].replaceAll("(..)", "$1:").substring(0, 17);
225	                        network.addWifiAccessPoint(WifiAccessPoint.from(mac, Integer.parseInt(values[i * 2])));
226	                    }
227	                    position.setNetwork(network);
228	
229	                    dateBuilder.setDateReverse(parser.nextInt(), parser.nextInt(), parser.nextInt());
230	
231	                    getLastLocation(position, dateBuilder.getDate());
232	                } else {
233	                    continue;
