package org.traccar.protocol;

import io.netty.channel.Channel;
import org.traccar.AbstractWireDecoder;
import org.traccar.model.CellTower;
import org.traccar.session.UnitSession;
import org.traccar.Protocol;
import org.traccar.helper.DateBuilder;
import org.traccar.helper.FieldCursor;
import org.traccar.helper.GrammarComposer;
import org.traccar.model.Network;
import org.traccar.model.Position;
import org.traccar.model.WifiAccessPoint;

import java.net.SocketAddress;
import java.util.LinkedList;
import java.util.List;
import java.util.regex.Pattern;

public class Tlt2hProtocolDecoder extends AbstractWireDecoder {

    public Tlt2hProtocolDecoder(Protocol protocol) {
        super(protocol);
    }

    private static final Pattern PATTERN_HEADER = new GrammarComposer()
            .number("#(d+)")                     // imei
            .expression("#[^#]*")                // user
            .number("#d*")                       // password
            .groupBegin()
            .number("#([01])")                   // door
            .number("#(d+)")                     // fuel voltage
            .number("#(d+)")                     // power
            .number("#(d+)")                     // battery
            .number("#(d+)")                     // temperature
            .groupEnd("?")
            .expression("#([^#]+)")              // status
            .number("#d+")                       // number of records
            .compile();

    private static final Pattern PATTERN_POSITION = new GrammarComposer()
            .text("#")
            .number("(?:(dd|dddd)|x*)")          // cell or voltage
            .groupBegin()
            .text("#")
            .groupBegin()
            .number("(d+),")                     // mcc
            .number("(d+),")                     // mnc
            .number("(x+),")                     // lac
            .number("(x+)")                      // cell id
            .groupEnd("?")
            .groupEnd("?")
            .text("$GPRMC,")
            .number("(?:(dd)(dd)(dd).d+)?,")     // time (hhmmss.sss)
            .expression("([AVL]),")              // validity
            .groupBegin()
            .number("(d+)(dd.d+),")              // latitude
            .expression("([NS]),")
            .number("(d+)(dd.d+),")              // longitude
            .number("([EW]),")
            .number("(d+.?d*)?,")                // speed
            .number("(d+.?d*)?,")                // course
            .number("(dd)(dd)(dd)")              // date (ddmmyy)
            .groupEnd("?")
            .any()
            .compile();

    private static final Pattern PATTERN_WIFI = new GrammarComposer()
            .text("#")
            .number("(?:(dd|dddd)|x+)")          // cell or voltage
            .expression("#?")
            .groupBegin()
            .number("(d+),")                     // mcc
            .number("(d+),")                     // mnc
            .number("(x+),")                     // lac
            .number("(x+)")                      // cell id
            .groupEnd("?")
            .text("$WIFI,")
            .number("(dd)(dd)(dd).d+,")          // time (hhmmss.sss)
            .expression("[AVL],")                // validity
            .expression("(.*)")                  // access points
            .number("(dd)(dd)(dd)")              // date (ddmmyy)
            .text("*")
            .number("xx")                        // checksum
            .compile();

    private void decodeStatus(Position position, String status) {
        switch (status) {
            case "AUTOSTART", "AUTO" -> position.set(Position.KEY_IGNITION, true);
            case "AUTOSTOP", "AUTOLOW" -> position.set(Position.KEY_IGNITION, false);
            case "TOWED" -> position.addAlarm(Position.ALARM_TOW);
            case "SHAKE" -> position.addAlarm(Position.ALARM_VIBRATION);
            case "SOS" -> position.addAlarm(Position.ALARM_SOS);
            case "DEF" -> position.addAlarm(Position.ALARM_POWER_CUT);
            case "BLP" -> position.addAlarm(Position.ALARM_LOW_BATTERY);
            case "CLP" -> position.addAlarm(Position.ALARM_LOW_POWER);
            case "OS" -> position.addAlarm(Position.ALARM_GEOFENCE_EXIT);
            case "RS" -> position.addAlarm(Position.ALARM_GEOFENCE_ENTER);
            case "OVERSPEED" -> position.addAlarm(Position.ALARM_OVERSPEED);
        }
    }

    @Override
    protected Object decode(
            Channel channel, SocketAddress remoteAddress, Object msg) throws Exception {

        String sentence = (String) msg;
        sentence = sentence.trim();

        String header = sentence.substring(0, sentence.indexOf('\r'));
        FieldCursor parser = new FieldCursor(PATTERN_HEADER, header);
        if (!parser.matches()) {
            return null;
        }

        UnitSession deviceSession = resolveUnitSession(channel, remoteAddress, parser.next());
        if (deviceSession == null) {
            return null;
        }

        Boolean door = null;
        Double adc = null;
        Double power = null;
        Double battery = null;
        Double temperature = null;
        if (parser.hasNext(5)) {
            door = parser.nextInt() == 1;
            adc = parser.nextInt() / 10.0;
            power = parser.nextInt() / 10.0;
            battery = parser.nextInt() / 10.0;
            temperature = parser.nextInt() / 10.0;
        }

        String status = parser.next();

        String[] messages = sentence.substring(
                sentence.indexOf('\n') + 1,
                sentence.endsWith("##") ? sentence.length() - 4 : sentence.length())
                .split("\r\n");
        List<Position> positions = new LinkedList<>();

        for (String message : messages) {
            Position position = new Position(wireName());
            position.setDeviceId(deviceSession.getDeviceId());

            if (message.contains("$GPRMC")) {

                parser = new FieldCursor(PATTERN_POSITION, message);
                if (parser.matches()) {

                    if (parser.hasNext()) {
                        int voltage = parser.nextInt();
                        position.set(Position.KEY_BATTERY, voltage > 100 ? voltage / 1000.0 : voltage / 10.0);
                    }

                    if (parser.hasNext(4)) {
                        Network network = new Network();
                        network.addCellTower(CellTower.from(
                                parser.nextInt(), parser.nextInt(), parser.nextHexInt(), parser.nextHexInt()));
                        position.setNetwork(network);
                    }

                    DateBuilder dateBuilder = new DateBuilder();
                    if (parser.hasNext(3)) {
                        dateBuilder.setTime(parser.nextInt(), parser.nextInt(), parser.nextInt());
                    }

                    position.setValid(parser.next().equals("A"));

                    if (parser.hasNext()) {

                        position.setLatitude(parser.nextCoordinate());
                        position.setLongitude(parser.nextCoordinate());
                        position.setSpeed(parser.nextDouble(0));
                        position.setCourse(parser.nextDouble(0));

                        dateBuilder.setDateReverse(parser.nextInt(), parser.nextInt(), parser.nextInt());
                        position.setTime(dateBuilder.getDate());

                    } else {
                        getLastLocation(position, null);
                    }

                } else {
                    continue;
                }

            } else if (message.contains("$WIFI")) {

                parser = new FieldCursor(PATTERN_WIFI, message);
                if (parser.matches()) {

                    if (parser.hasNext()) {
                        int voltage = parser.nextInt();
                        position.set(Position.KEY_BATTERY, voltage > 100 ? voltage / 1000.0 : voltage / 10.0);
                    }

                    Network network = new Network();
                    if (parser.hasNext(4)) {
                        network.addCellTower(CellTower.from(
                                parser.nextInt(), parser.nextInt(), parser.nextHexInt(), parser.nextHexInt()));
                    }

                    DateBuilder dateBuilder = new DateBuilder()
                            .setTime(parser.nextInt(), parser.nextInt(), parser.nextInt());

                    String[] values = parser.next().split(",");
                    for (int i = 0; i < values.length / 2; i++) {
                        String mac = values[i * 2 + 1].replaceAll("(..)", "$1:").substring(0, 17);
                        network.addWifiAccessPoint(WifiAccessPoint.from(mac, Integer.parseInt(values[i * 2])));
                    }
                    position.setNetwork(network);

                    dateBuilder.setDateReverse(parser.nextInt(), parser.nextInt(), parser.nextInt());

                    getLastLocation(position, dateBuilder.getDate());
                } else {
                    continue;
                }

            } else {

                getLastLocation(position, null);

            }

            position.set(Position.KEY_DOOR, door);
            position.set(Position.PREFIX_ADC + 1, adc);
            position.set(Position.KEY_POWER, power);
            position.set(Position.KEY_BATTERY, battery);
            position.set(Position.PREFIX_TEMP + 1, temperature);
            decodeStatus(position, status);

            positions.add(position);
        }

        return positions.isEmpty() ? null : positions;
    }

}

